import { readFileSync, statSync } from 'node:fs';
import { resolve, join } from 'node:path';
import { pathToFileURL } from 'node:url';

// Cargo.lock is generated by Cargo; accept exactly one locked CEF sys package.
// This narrow reader avoids invoking a package manager during run-release.
export function lockedCefBinding(lock) {
    const versions = [...lock.matchAll(/^name = "cef-dll-sys"\nversion = "([^"]+)"$/gm)];
    if (versions.length !== 1) throw new Error('Expected one cef-dll-sys package in Cargo.lock.');
    return versions[0][1];
}

// cef-dll-sys 154 copies the resolved distribution beside the executable. Use
// that artifact, never the first (possibly stale) build-cache directory.
export function cefRuntimeDirectory(directory, bindingVersion) {
    const version = bindingVersion.split('+')[1];
    if (!/^\d+\.\d+\.\d+$/.test(version ?? '')) {
        throw new Error('The resolved CEF binding must identify its CEF runtime version.');
    }
    const runtime = resolve(directory);
    const archive = JSON.parse(readFileSync(join(runtime, 'archive.json'), 'utf8'));
    const archiveVersion = /^cef_binary_(\d+\.\d+\.\d+)\+.+_linux64_minimal\.tar\.bz2$/.exec(archive.name ?? '')?.[1];
    if (archiveVersion !== version || archive.type !== 'minimal') {
        throw new Error(`CEF runtime does not match resolved binding ${bindingVersion}. Rebuild with a matching CEF_PATH or unset it.`);
    }
    for (const file of ['libcef.so', 'icudtl.dat', 'resources.pak', 'chrome_100_percent.pak', 'chrome_200_percent.pak']) {
        if (!statSync(join(runtime, file)).isFile()) {
            throw new Error(`CEF runtime resource is not a file: ${file}`);
        }
    }
    if (!statSync(join(runtime, 'locales')).isDirectory()) {
        throw new Error('CEF runtime locales directory is missing.');
    }
    return runtime;
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
    try {
        if (process.argv.length !== 4) throw new Error('Usage: cef-runtime.mjs <binary-directory> <Cargo.lock>');
        console.log(cefRuntimeDirectory(process.argv[2], lockedCefBinding(readFileSync(process.argv[3], 'utf8'))));
    } catch (error) {
        console.error(`[cef] ${error.message}`);
        process.exitCode = 1;
    }
}
